-- FH Habibur Tech database schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','accountant','employee');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role public.app_role not null default 'employee',created_at timestamptz not null default now());
create table public.clients(id uuid primary key default gen_random_uuid(),name text not null,business_name text,phone text,email text,facebook_page text,notes text,status text not null default 'active' check(status in('active','inactive','prospect')),created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.campaigns(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id),name text not null,platform text not null default 'Meta',objective text,budget_usd numeric(14,2) not null default 0 check(budget_usd>=0),spent_usd numeric(14,2) not null default 0 check(spent_usd>=0),exchange_rate numeric(14,4) not null default 0 check(exchange_rate>=0),status text not null default 'active' check(status in('draft','active','paused','completed')),start_date date,end_date date,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(),client_id uuid not null references public.clients(id),amount_bdt numeric(14,2) not null check(amount_bdt>0),payment_date date not null default current_date,method text not null default 'Bank transfer',reference text,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.expenses(id uuid primary key default gen_random_uuid(),title text not null,category text not null default 'Other',amount_bdt numeric(14,2) not null check(amount_bdt>=0),expense_date date not null default current_date,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.dollar_transactions(id uuid primary key default gen_random_uuid(),transaction_type text not null check(transaction_type in('purchase','usage','sale','adjustment')),amount_usd numeric(14,2) not null check(amount_usd>0),exchange_rate numeric(14,4) not null check(exchange_rate>=0),amount_bdt numeric(14,2) generated always as(round(amount_usd*exchange_rate,2)) stored,transaction_date date not null default current_date,client_id uuid references public.clients(id),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.invoices(id uuid primary key default gen_random_uuid(),invoice_number text not null unique,client_id uuid not null references public.clients(id),issue_date date not null default current_date,due_date date,subtotal_bdt numeric(14,2) not null default 0,status text not null default 'unpaid' check(status in('draft','unpaid','partially_paid','paid','void')),notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.invoice_items(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id) on delete cascade,description text not null,quantity numeric(12,2) not null default 1,unit_price_bdt numeric(14,2) not null default 0);
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id),action text not null,table_name text not null,record_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),'employee'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.current_user_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create or replace function public.is_admin_or_accountant() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_user_role() in('admin','accountant'),false) $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','clients','campaigns','payments','expenses','dollar_transactions','invoices','invoice_items','audit_logs'] LOOP EXECUTE format('alter table public.%I enable row level security',t); END LOOP; END $$;
create policy "profiles read self admin" on public.profiles for select using(id=auth.uid() or public.current_user_role()='admin');
create policy "admin updates profiles" on public.profiles for update using(public.current_user_role()='admin') with check(public.current_user_role()='admin');
create policy "staff read clients" on public.clients for select to authenticated using(true);
create policy "staff add clients" on public.clients for insert to authenticated with check(created_by=auth.uid());
create policy "finance update clients" on public.clients for update to authenticated using(public.is_admin_or_accountant()) with check(public.is_admin_or_accountant());
create policy "admin delete clients" on public.clients for delete to authenticated using(public.current_user_role()='admin');
create policy "staff read campaigns" on public.campaigns for select to authenticated using(true);
create policy "staff create campaigns" on public.campaigns for insert to authenticated with check(created_by=auth.uid());
create policy "finance update campaigns" on public.campaigns for update to authenticated using(public.is_admin_or_accountant()) with check(public.is_admin_or_accountant());
create policy "admin delete campaigns" on public.campaigns for delete to authenticated using(public.current_user_role()='admin');
create policy "finance read payments" on public.payments for select to authenticated using(public.is_admin_or_accountant());
create policy "finance insert payments" on public.payments for insert to authenticated with check(public.is_admin_or_accountant() and created_by=auth.uid());
create policy "admin manage payments" on public.payments for all to authenticated using(public.current_user_role()='admin') with check(public.current_user_role()='admin');
create policy "finance read expenses" on public.expenses for select to authenticated using(public.is_admin_or_accountant());
create policy "finance manage expenses" on public.expenses for all to authenticated using(public.is_admin_or_accountant()) with check(public.is_admin_or_accountant());
create policy "finance read dollar ledger" on public.dollar_transactions for select to authenticated using(public.is_admin_or_accountant());
create policy "finance manage dollar ledger" on public.dollar_transactions for all to authenticated using(public.is_admin_or_accountant()) with check(public.is_admin_or_accountant());
create policy "finance read invoices" on public.invoices for select to authenticated using(public.is_admin_or_accountant());
create policy "finance manage invoices" on public.invoices for all to authenticated using(public.is_admin_or_accountant()) with check(public.is_admin_or_accountant());
create policy "finance read invoice items" on public.invoice_items for select to authenticated using(exists(select 1 from public.invoices i where i.id=invoice_id));
create policy "finance manage invoice items" on public.invoice_items for all to authenticated using(public.is_admin_or_accountant()) with check(public.is_admin_or_accountant());
create policy "admin read audit logs" on public.audit_logs for select to authenticated using(public.current_user_role()='admin');
create policy "signed-in append audit logs" on public.audit_logs for insert to authenticated with check(actor_id=auth.uid());
